using System.Collections;
using System.Collections.Generic;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class DiceRollingHandler : ReferenceSingleton<DiceRollingHandler>
{
	[Header("Rolling Variables")]
	[SerializeField]
	private FloatReference zGravityFloatReference;

	[SerializeField]
	private FloatReference timeToIncreaseGravityFloatReference;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnRollDices;

	[ShowNonSerializedField]
	private bool isDiceRolling;

	[ShowNonSerializedField]
	private int dicesRolledCounter;

	[ShowNonSerializedField]
	private List<DiceInstance> diceToPosition = new List<DiceInstance>();

	[ShowNonSerializedField]
	private int dicesPositionedCounter;

	private List<DiceInstance> diceToRollList = new List<DiceInstance>();

	public bool IsDiceRolling => isDiceRolling;

	public void SetIsDiceRolling(bool value)
	{
		Debug.Log("ROLL DICE HANDLER: SetIsDiceRolling: " + value);
		isDiceRolling = value;
	}

	public void TrySettingIsDiceRollingToFalse()
	{
		if (!IsAnyDiceRolling())
		{
			SetIsDiceRolling(value: false);
		}
	}

	public bool IsAnyDiceRolling()
	{
		if (diceToRollList.Count > 0)
		{
			for (int i = 0; i < diceToRollList.Count; i++)
			{
				if (diceToRollList[i].DiceState == DiceState.Rolling)
				{
					return true;
				}
			}
		}
		return false;
	}

	public void RollDieWithDieSetup(List<DiceInstance> _diceToRollList, bool killTrail = true)
	{
		for (int i = 0; i < _diceToRollList.Count; i++)
		{
			if (killTrail)
			{
				_diceToRollList[i].KillTrail();
			}
			_diceToRollList[i].SetupDiceToRoll();
		}
		diceToRollList.AddRange(_diceToRollList);
		RollDiceDefault();
	}

	public void RollDice(List<DiceInstance> _diceToRollList, bool startOfTurnHandDiceRolling = false)
	{
		diceToRollList.AddRange(_diceToRollList);
		RollDiceDefault(startOfTurnHandDiceRolling);
	}

	private void RollDiceDefault(bool startOfTurnHandDiceRolling = false)
	{
		SetIsDiceRolling(value: true);
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		Debug.LogFormat("ROLL DICE HANDLER: Start dicesRolledCounter {0}", dicesRolledCounter);
		if (diceToRollList.Count > 0)
		{
			for (int i = 0; i < diceToRollList.Count; i++)
			{
				if (diceToRollList[i].DiceState != DiceState.Rolling && diceToRollList[i].DiceState != DiceState.FinishedRolling)
				{
					diceToRollList[i].DiceRolling.RollDice(startOfTurnHandDiceRolling);
				}
			}
			OnRollDices.Raise();
			InvokeAlternatives.Invoke(this, timeToIncreaseGravityFloatReference.Value, delegate
			{
				Physics.gravity = new Vector3(0f, 0f, zGravityFloatReference.Value);
			});
			Debug.Log("ROLL DICE HANDLER: Started rolling all dices");
		}
		else
		{
			Debug.Log("ROLL DICE HANDLER: No dice to roll going direct to next step");
			AfterDiceFinalPositionedOrAfterBottledAuroraCanceled(startOfTurnHandDiceRolling);
		}
	}

	public void SpawnAndRollEnemyDice()
	{
		int count = diceToRollList.Count;
		for (int i = 0; i < ReferenceSingleton<AssetsReference>.instance.CurrentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
		{
			CorruptedAnimalActivation component = ReferenceSingleton<AssetsReference>.instance.CurrentCorruptedAnimals.activeCorruptedAnimals[i].GetComponent<CorruptedAnimalActivation>();
			if (component.GetDiceAmount() > 0)
			{
				component.Spawn3DDice();
				List<DiceInstance> diceInstancesToRoll = component.GetDiceInstancesToRoll();
				diceToRollList.AddRange(diceInstancesToRoll);
			}
		}
		count = diceToRollList.Count - count;
		Debug.LogFormat("ROLL DICE HANDLER: Enemy dicesToBeRolledAmount {0}", diceToRollList.Count);
	}

	public void SpawnAndRollCompanionDice()
	{
		int count = diceToRollList.Count;
		for (int i = 0; i < ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions.Count; i++)
		{
			CompanionAbility component = ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions[i].GetComponent<CompanionAbility>();
			component.Spawn3DDice();
			List<DiceInstance> diceInstancesToRoll = component.GetDiceInstancesToRoll();
			diceToRollList.AddRange(diceInstancesToRoll);
		}
		count = diceToRollList.Count - count;
		Debug.LogFormat("ROLL DICE HANDLER: Companion dicesToBeRolledAmount {0}", count);
	}

	public void OnRollingDiceEnded(bool startOfTurnHandDiceRolling)
	{
		dicesRolledCounter++;
		Debug.LogFormat("ROLL DICE HANDLER: dicesRolledCounter = {0}/ dicesToBeRolledAmount = {1}", dicesRolledCounter, diceToRollList.Count);
		if (dicesRolledCounter >= diceToRollList.Count)
		{
			dicesRolledCounter = 0;
			Debug.LogFormat("ROLL DICE HANDLER: dicesRolledCounter {0}", dicesRolledCounter);
			ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition(delegate
			{
				AfterDicePositioned(startOfTurnHandDiceRolling);
			});
			FinishedRollingDiceEnemiesAndCompanions(startOfTurnHandDiceRolling);
			Physics.gravity = new Vector3(0f, 0f, 9.81f);
			diceToPosition.AddRange(diceToRollList);
			diceToRollList.Clear();
			Debug.Log("ROLL DICE HANDLER: Ended rolling all dices");
		}
	}

	private void FinishedRollingDiceEnemiesAndCompanions(bool startOfTurnHandDiceRolling)
	{
		for (int i = 0; i < diceToRollList.Count; i++)
		{
			DiceInstance diceInstance = diceToRollList[i];
			if (diceInstance.DiceOwnerEnum != 0)
			{
				diceInstance.PlayAnimationAfterDiceDrawCompanionsAndEnemies(delegate
				{
					AfterDicePositioned(startOfTurnHandDiceRolling);
				});
			}
		}
	}

	private void AfterDicePositioned(bool startOfTurnHandDiceRolling)
	{
		dicesPositionedCounter++;
		Debug.LogFormat("ROLL DICE HANDLER: dicesPositionedCounter = {0}/ diceToPosition.Count = {1}", dicesPositionedCounter, diceToPosition.Count);
		if (dicesPositionedCounter < diceToPosition.Count || IsAnyDiceRolling())
		{
			return;
		}
		diceToPosition.Clear();
		dicesPositionedCounter = 0;
		Debug.LogFormat("ROLL DICE HANDLER: diceToPosition.Count {0}", diceToPosition.Count);
		Debug.LogFormat("ROLL DICE HANDLER: dicesPositionedCounter {0}", dicesPositionedCounter);
		if (startOfTurnHandDiceRolling && (bool)ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData)
		{
			if (!ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData.AlreadyUsed)
			{
				Debug.LogFormat("ROLL DICE HANDLER: BottledAurora active and not used yet");
				Debug.LogFormat("ROLL DICE HANDLER: PlayerDiceHandHolder.Instance.handDices.Count: " + ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count);
				if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > 0 && ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive())
				{
					Debug.LogFormat("ROLL DICE HANDLER: BottledAurora PlayerDiceHandHolder.Instance.handDices.Count && AssetsReference.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive()");
					if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState)
					{
						ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAction(ActiveBottledAuroraOmen());
						return;
					}
					ReferenceSingleton<MiscOmensHandler>.Instance.ActivateBottledAuroraOmen();
					Debug.LogFormat("ROLL DICE HANDLER: ActivateBottledAuroraOmen()");
					return;
				}
			}
			else
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData.AlreadyUsed = false;
			}
		}
		AfterDiceFinalPositionedOrAfterBottledAuroraCanceled(startOfTurnHandDiceRolling);
		static IEnumerator ActiveBottledAuroraOmen()
		{
			yield return InvokeAlternatives.WaitOneFrame();
			if (ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive())
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.ActivateBottledAuroraOmen();
				Debug.LogFormat("ROLL DICE HANDLER: ActivateBottledAuroraOmen()");
			}
		}
	}

	public void BottledAuroraCanceled()
	{
		if ((bool)ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData.AlreadyUsed = false;
		}
		AfterDiceFinalPositionedOrAfterBottledAuroraCanceled(startOfTurnHandDiceRolling: true);
	}

	private void AfterDiceFinalPositionedOrAfterBottledAuroraCanceled(bool startOfTurnHandDiceRolling)
	{
		if (startOfTurnHandDiceRolling)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerBoostActiveRemoveIt();
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.SetDefaultDrawDicesAmount();
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDrawDiceAmountWithOmensModifiers();
		}
		Debug.LogFormat("ROLL DICE HANDLER: AfterDicePositionedOrAfterBottledAuroraCanceled");
		TrySettingIsDiceRollingToFalse();
	}
}
